//! Checks that warpsign-core reproduces Python warpsign's outputs exactly.
//! Fixtures are generated by `tools/gen_fixtures.py`.

use std::collections::{BTreeMap, BTreeSet, HashSet};
use std::path::PathBuf;

use base64::Engine;
use plist::{Dictionary, Value};
use serde_json::{Value as Json, json};
use warpsign_core::bundle_mapping::BundleMapping;
use warpsign_core::entitlements::EntitlementsProcessor;
use warpsign_core::{ProfileType, PyRandom};

fn load_fixture(name: &str) -> Json {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures")
        .join(name);
    let contents = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("reading {}: {e}", path.display()));
    serde_json::from_str(&contents).unwrap()
}

fn cases(fixture: &Json) -> &Vec<Json> {
    fixture["cases"].as_array().expect("fixture has cases")
}

fn str_of(value: &Json) -> &str {
    value.as_str().expect("string")
}

fn strings(value: &Json) -> Vec<String> {
    value
        .as_array()
        .expect("array")
        .iter()
        .map(|v| str_of(v).to_owned())
        .collect()
}

fn json_to_plist(value: &Json) -> Value {
    match value {
        Json::Bool(b) => Value::Boolean(*b),
        Json::String(s) => Value::String(s.clone()),
        Json::Number(n) => match n.as_i64() {
            Some(i) => Value::Integer(i.into()),
            None => Value::Real(n.as_f64().unwrap()),
        },
        Json::Array(items) => Value::Array(items.iter().map(json_to_plist).collect()),
        Json::Object(map) => Value::Dictionary(
            map.iter()
                .map(|(k, v)| (k.clone(), json_to_plist(v)))
                .collect(),
        ),
        Json::Null => panic!("null has no plist equivalent"),
    }
}

fn plist_to_json(value: &Value) -> Json {
    match value {
        Value::Boolean(b) => json!(b),
        Value::String(s) => json!(s),
        Value::Integer(i) => json!(i.as_signed().unwrap()),
        Value::Real(r) => json!(r),
        Value::Array(items) => Json::Array(items.iter().map(plist_to_json).collect()),
        Value::Dictionary(dict) => dict_to_json(dict),
        other => panic!("unexpected plist value in entitlements: {other:?}"),
    }
}

fn dict_to_json(dict: &Dictionary) -> Json {
    Json::Object(
        dict.iter()
            .map(|(k, v)| (k.clone(), plist_to_json(v)))
            .collect(),
    )
}

fn dict(value: &Json) -> Dictionary {
    match json_to_plist(value) {
        Value::Dictionary(dict) => dict,
        _ => panic!("expected an object"),
    }
}

#[test]
fn python_random_matches() {
    let alphabet: Vec<char> = ('a'..='z').chain('0'..='9').collect();
    for case in cases(&load_fixture("python_random.json")) {
        let seed = str_of(&case["seed"]);

        let mut rng = PyRandom::from_str_seed(seed);
        for expected in case["random"].as_array().unwrap() {
            assert_eq!(rng.random(), expected.as_f64().unwrap(), "seed {seed:?}");
        }

        let mut rng = PyRandom::from_str_seed(seed);
        assert_eq!(
            rng.choices(&alphabet, 20),
            str_of(&case["choices"]),
            "seed {seed:?}"
        );
    }
}

#[test]
fn random_ids_match() {
    for case in cases(&load_fixture("random_ids.json")) {
        let mut mapping = BundleMapping::new(
            vec!["ABCDE12345".into()],
            str_of(&case["team_id"]),
            "com.example.app",
            true,
        );
        assert_eq!(
            mapping.gen_random_id(str_of(&case["original_id"])),
            str_of(&case["random_id"]),
            "{case}"
        );
    }
}

/// Mirrors `run_mapping_case` in tools/gen_fixtures.py
#[test]
fn bundle_mapping_matches() {
    for case in cases(&load_fixture("bundle_mapping.json")) {
        let name = str_of(&case["name"]);
        let expected = &case["expected"];

        let mut mapping = BundleMapping::new(
            strings(&case["original_team_ids"]),
            str_of(&case["new_team_id"]),
            str_of(&case["main_bundle_id"]),
            case["randomize"].as_bool().unwrap(),
        );
        mapping.force_original_id = case["force_original_id"].as_bool().unwrap();
        mapping.profile_type = str_of(&case["profile_type"]).parse().unwrap();

        let components = case["components"].as_array().unwrap();
        let mut app_groups = BTreeSet::new();
        let mut icloud_containers = BTreeSet::new();
        let mut mapped_bundle_ids = Vec::new();
        for component in components {
            mapped_bundle_ids.push(mapping.map_bundle_id(str_of(&component["bundle_id"])));
            let (groups, containers) =
                mapping.extract_resources_from_entitlements(&dict(&component["entitlements"]));
            app_groups.extend(groups);
            icloud_containers.extend(containers);
        }

        assert_eq!(
            mapped_bundle_ids,
            strings(&expected["mapped_bundle_ids"]),
            "{name}: bundle IDs"
        );
        assert_eq!(
            app_groups.into_iter().collect::<Vec<_>>(),
            strings(&expected["app_groups"]),
            "{name}: app groups"
        );
        assert_eq!(
            icloud_containers.into_iter().collect::<Vec<_>>(),
            strings(&expected["icloud_containers"]),
            "{name}: iCloud containers"
        );

        // Registration happens in the orchestrator, so take its result from the fixture
        mapping.registered_identifiers = strings(&expected["registered_identifiers"])
            .into_iter()
            .collect::<HashSet<_>>();

        for ((component, bundle_id), expected_ents) in components
            .iter()
            .zip(&mapped_bundle_ids)
            .zip(expected["mapped_entitlements"].as_array().unwrap())
        {
            let entitlements = dict(&component["entitlements"]);
            let mapped = if entitlements.is_empty() {
                Dictionary::new()
            } else {
                mapping.map_entitlements(&entitlements, Some(bundle_id))
            };
            assert_eq!(
                &dict_to_json(&mapped),
                expected_ents,
                "{name}: entitlements of {bundle_id}"
            );
        }

        let mappings: BTreeMap<_, _> = mapping
            .mappings()
            .iter()
            .map(|(k, v)| {
                (
                    k.clone(),
                    json!({"new_id": v.new_id, "id_type": v.id_type.name()}),
                )
            })
            .collect();
        assert_eq!(json!(mappings), expected["mappings"], "{name}: mappings");

        let patches: BTreeMap<_, _> = mapping.binary_patches().into_iter().collect();
        assert_eq!(
            json!(patches),
            expected["binary_patches"],
            "{name}: binary patches"
        );
    }
}

#[test]
fn entitlements_processor_matches() {
    let capabilities = load_fixture("capabilities_response.json");
    for case in cases(&load_fixture("entitlements_processor.json")) {
        let name = str_of(&case["name"]);
        let profile_type: ProfileType = str_of(&case["profile_type"]).parse().unwrap();

        let plan = EntitlementsProcessor::new(&capabilities, profile_type)
            .process(&dict(&case["entitlements"]));

        assert_eq!(
            plan.capabilities_to_enable.into_iter().collect::<Vec<_>>(),
            strings(&case["expected"]["capabilities_to_enable"]),
            "{name}: capabilities"
        );
        assert_eq!(
            plan.entitlements_to_remove.into_iter().collect::<Vec<_>>(),
            strings(&case["expected"]["entitlements_to_remove"]),
            "{name}: removals"
        );
    }
}

/// Mirrors `inspection_cases` in tools/gen_fixtures.py
#[test]
fn app_inspection_matches() {
    use warpsign_core::inspect::{inspect_app_with, slash_path, team_ids};

    for case in cases(&load_fixture("app_inspection.json")) {
        let name = str_of(&case["name"]);
        let dir = tempfile::tempdir().unwrap();
        let app = dir.path().join("App.app");
        for file in case["files"].as_array().unwrap() {
            let path = app.join(str_of(&file["path"]));
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            if file.get("info_plist").is_some() {
                json_to_plist(&file["info_plist"])
                    .to_file_xml(&path)
                    .unwrap();
            } else {
                std::fs::write(&path, b"stub").unwrap();
            }
        }

        let stubbed = &case["entitlements"];
        let components = inspect_app_with(&app, |executable| {
            let relative = slash_path(executable.strip_prefix(&app).unwrap());
            stubbed.get(&relative).map(dict).unwrap_or_default()
        })
        .unwrap_or_else(|e| panic!("{name}: {e}"));

        let actual: Vec<Json> = components
            .iter()
            .map(|c| {
                json!({
                    "path": slash_path(&c.path),
                    "bundle_id": c.bundle_id,
                    "executable": slash_path(&c.executable),
                    "is_primary": c.is_primary,
                    "entitlements_bundle_id": c.entitlements_bundle_id,
                    "entitlements": dict_to_json(&c.entitlements),
                })
            })
            .collect();
        assert_eq!(
            Json::Array(actual),
            case["expected"]["components"],
            "{name}: components"
        );
        assert_eq!(
            team_ids(&components),
            strings(&case["expected"]["team_ids"]),
            "{name}: team IDs"
        );
    }
}

fn patching_options(options: &Json) -> warpsign_core::info_plist::PatchingOptions {
    use warpsign_core::info_plist::{PatchingOptions, StatusBarStyle, UiStyle};

    let flag = |key: &str| options.get(key).and_then(Json::as_bool);
    let defaults = PatchingOptions::default();
    PatchingOptions {
        patch_ids: flag("patch_ids").unwrap_or(defaults.patch_ids),
        force_original_id: flag("force_original_id").unwrap_or_default(),
        bundle_name: options
            .get("bundle_name")
            .and_then(Json::as_str)
            .map(String::from),
        patch_all_devices: flag("patch_all_devices").unwrap_or_default(),
        patch_file_sharing: flag("patch_file_sharing").unwrap_or_default(),
        patch_promotion: flag("patch_promotion").unwrap_or_default(),
        patch_fullscreen: flag("patch_fullscreen").unwrap_or_default(),
        patch_orientation: flag("patch_orientation").unwrap_or_default(),
        patch_game_mode: flag("patch_game_mode").unwrap_or_default(),
        patch_status_bar: match options.get("patch_status_bar").and_then(Json::as_str) {
            None => StatusBarStyle::Default,
            Some("hidden") => StatusBarStyle::Hidden,
            Some("light") => StatusBarStyle::Light,
            Some("dark") => StatusBarStyle::Dark,
            Some(other) => panic!("unknown status bar style {other}"),
        },
        patch_user_interface_style: match options
            .get("patch_user_interface_style")
            .and_then(Json::as_str)
        {
            None => UiStyle::Automatic,
            Some("light") => UiStyle::Light,
            Some("dark") => UiStyle::Dark,
            Some(other) => panic!("unknown UI style {other}"),
        },
        remove_url_schemes: flag("remove_url_schemes").unwrap_or_default(),
    }
}

/// Mirrors `info_plist_cases` in tools/gen_fixtures.py
#[test]
fn info_plist_patching_matches() {
    use warpsign_core::info_plist::InfoPlistPatcher;

    for case in cases(&load_fixture("info_plist_patching.json")) {
        let name = str_of(&case["name"]);

        let mut mapping = BundleMapping::new(
            strings(&case["original_team_ids"]),
            str_of(&case["new_team_id"]),
            str_of(&case["main_bundle_id"]),
            case["randomize"].as_bool().unwrap(),
        );
        mapping.force_original_id = case["force_original_id"].as_bool().unwrap();
        mapping.profile_type = str_of(&case["profile_type"]).parse().unwrap();
        for component in case["components"].as_array().unwrap() {
            mapping.map_bundle_id(str_of(&component["bundle_id"]));
            mapping.extract_resources_from_entitlements(&dict(&component["entitlements"]));
        }
        mapping.registered_identifiers = strings(&case["registered_identifiers"])
            .into_iter()
            .collect::<HashSet<_>>();

        let dir = tempfile::tempdir().unwrap();
        let mut patcher = InfoPlistPatcher::new(patching_options(&case["options"]));
        for entry in case["info_plists"].as_array().unwrap() {
            let relative = str_of(&entry["path"]);
            let path = dir.path().join(relative).join("Info.plist");
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            json_to_plist(&entry["info_plist"])
                .to_file_xml(&path)
                .unwrap();

            let patched = patcher
                .patch_file(&path, &mut mapping, relative.is_empty())
                .unwrap();

            assert_eq!(
                dict_to_json(&patched),
                entry["expected"],
                "{name}: Info.plist of {relative:?}"
            );
            let on_disk = plist::Value::from_file(&path).unwrap();
            assert_eq!(
                plist_to_json(&on_disk),
                entry["expected"],
                "{name}: file on disk"
            );
        }

        // Then a binary, with the state the Info.plists left
        let decode = |key: &str| {
            base64::engine::general_purpose::STANDARD
                .decode(str_of(&case["binary"][key]))
                .unwrap()
        };
        let binary = dir.path().join("Binary");
        std::fs::write(&binary, decode("input")).unwrap();
        patcher.patch_binary(&binary, &mapping).unwrap();
        assert_eq!(
            std::fs::read(&binary).unwrap(),
            decode("expected"),
            "{name}: binary"
        );
    }
}
